-- Colporteurs: municipality-based teams, rotations, historical reports.
-- Run after 15_laundry.sql. Re-runnable; existing unrecognized city names are preserved.
begin;
create table if not exists public.colombia_municipalities (
  code text primary key check (code ~ '^[0-9]{5}$'),
  name text not null,
  department text not null,
  type text not null
);
alter table public.colombia_municipalities enable row level security;
drop policy if exists municipalities_read on public.colombia_municipalities;
create policy municipalities_read on public.colombia_municipalities for select to authenticated using (true);
revoke all on public.colombia_municipalities from public, anon, authenticated;
grant select on public.colombia_municipalities to authenticated;

