on conflict(code) do update set name=excluded.name,department=excluded.department,type=excluded.type;

alter table public.teams add column if not exists municipality_code text references public.colombia_municipalities(code);
alter table public.rotations add column if not exists municipality_code text references public.colombia_municipalities(code);
alter table public.sales_reports add column if not exists municipality_code text references public.colombia_municipalities(code);
alter table public.sales_reports add column if not exists team_name_snapshot text;
create index if not exists sales_reports_date_person_idx on public.sales_reports(report_date, person_id);

-- Backfill only unambiguous matches. Never guess between same-named municipalities.
update public.teams t set municipality_code = m.code
from public.colombia_municipalities m
where t.municipality_code is null and lower(trim(t.name)) = lower(m.name)
  and (select count(*) from public.colombia_municipalities m2 where lower(m2.name)=lower(m.name)) = 1;
update public.rotations r set municipality_code = m.code
from public.colombia_municipalities m
where r.municipality_code is null and lower(trim(r.city)) = lower(m.name)
  and (select count(*) from public.colombia_municipalities m2 where lower(m2.name)=lower(m.name)) = 1;
update public.sales_reports s set municipality_code = m.code
from public.colombia_municipalities m
where s.municipality_code is null and lower(trim(s.city)) = lower(m.name)
  and (select count(*) from public.colombia_municipalities m2 where lower(m2.name)=lower(m.name)) = 1;
-- Freeze legacy team labels before renaming any teams.
update public.sales_reports s set team_name_snapshot = coalesce(t.name, 'Sin equipo')
from public.teams t where s.team_id=t.id and s.team_name_snapshot is null;
update public.sales_reports set team_name_snapshot = 'Sin equipo' where team_name_snapshot is null;
update public.teams t set name = m.name || ' (' || m.department || ')'
from public.colombia_municipalities m where t.municipality_code=m.code
  and not exists (select 1 from public.teams other where other.id<>t.id and other.name=m.name || ' (' || m.department || ')');

create or replace function public.team_municipality_on(p_team uuid, p_date date)
returns text language sql stable set search_path = public as $fn$
  select case when r.id is not null then r.municipality_code else t.municipality_code end
  from public.teams t left join public.rotations r on r.team_id=t.id
    and p_date >= r.start_date and p_date < r.end_date where t.id=p_team;
$fn$;
create or replace function public.team_name_on(p_team uuid, p_date date)
returns text language sql stable set search_path = public as $fn$
  select coalesce(m.name || ' (' || m.department || ')', r.city, t.name)
  from public.teams t left join public.rotations r on r.team_id=t.id
    and p_date >= r.start_date and p_date < r.end_date
  left join public.colombia_municipalities m
    on m.code=case when r.id is not null then r.municipality_code else t.municipality_code end
  where t.id=p_team;
$fn$;
create or replace function public.person_city_on(p_person uuid, p_date date)
returns text language sql stable set search_path = public as $fn$
  select coalesce(r.city, m.name, p.base_city)
  from public.people p left join public.teams t on t.id=p.team_id
  left join public.colombia_municipalities m on m.code=t.municipality_code
  left join public.rotations r on r.team_id=t.id and p_date>=r.start_date and p_date<r.end_date
  where p.id=p_person;
$fn$;

create or replace view public.v_colporteur_teams with (security_invoker = on) as
select t.id, public.team_name_on(t.id, public.cepev_today()) as name,
  t.name as base_name, t.municipality_code, t.is_active,
  m.name as base_city, m.department,
  public.team_municipality_on(t.id, public.cepev_today()) as current_municipality_code,
  (select count(*)::int from public.people p where p.team_id=t.id and p.kind='Colportor') as members_count
from public.teams t left join public.colombia_municipalities m on m.code=t.municipality_code;

create or replace function public.colporteur_team_save(p_municipality text, p_id uuid default null)
returns public.teams language plpgsql security definer set search_path = public as $fn$
declare v_m public.colombia_municipalities%rowtype; v_team public.teams%rowtype;
begin
  perform public.assert_can_write();
  perform pg_advisory_xact_lock(160026);
  select * into v_m from public.colombia_municipalities where code=p_municipality;
  if not found then raise exception 'Selecciona un municipio del listado.'; end if;
  if exists (select 1 from public.teams where municipality_code=p_municipality and (p_id is null or id<>p_id)) then
    raise exception 'Ya existe un equipo con ese municipio base.';
  end if;
  if p_id is null then
    insert into public.teams(name,municipality_code) values (v_m.name || ' (' || v_m.department || ')',v_m.code) returning * into v_team;
  else
    update public.teams set name=v_m.name || ' (' || v_m.department || ')',municipality_code=v_m.code
    where id=p_id and is_active returning * into v_team;
    if not found then raise exception 'El equipo no existe o esta inactivo.'; end if;
  end if;
  perform public.log_action('colporteur_team_save','teams',v_team.id,'Equipo asignado a ' || v_team.name);
  return v_team;
end;
$fn$;

create or replace function public.colporteur_assign_team(p_person uuid, p_team uuid)
returns void language plpgsql security definer set search_path = public as $fn$
begin
  perform public.assert_can_write();
  perform pg_advisory_xact_lock(160026);
  if p_team is not null and not exists(select 1 from public.teams where id=p_team and is_active and municipality_code is not null) then
    raise exception 'Selecciona un equipo activo con municipio asignado.';
  end if;
  update public.people set team_id=p_team where id=p_person and kind='Colportor';
  if not found then raise exception 'Selecciona un colportor valido.'; end if;
  perform public.log_action('colporteur_assign_team','people',p_person,'Asignacion de equipo actualizada');
end;
$fn$;

create or replace function public.colporteur_rotation_save(
  p_team uuid, p_municipality text, p_start date, p_end date, p_id uuid default null
) returns public.rotations language plpgsql security definer set search_path = public as $fn$
declare v_m public.colombia_municipalities%rowtype; v_row public.rotations%rowtype; v_old public.rotations%rowtype;
begin
  perform public.assert_can_write();
  perform pg_advisory_xact_lock(160026);
  if p_start is null or p_end is null or p_end<=p_start then raise exception 'La salida debe ser posterior al inicio.'; end if;
  if not exists(select 1 from public.teams where id=p_team and is_active and municipality_code is not null) then
    raise exception 'Asigna primero un municipio base al equipo.';
  end if;
  select * into v_m from public.colombia_municipalities where code=p_municipality;
  if not found then raise exception 'Selecciona un municipio del listado.'; end if;
  if p_id is not null then
    select * into v_old from public.rotations where id=p_id for update;
    if not found then raise exception 'La rotacion no existe.'; end if;
    if v_old.team_id<>p_team then raise exception 'No se puede cambiar el equipo de una rotacion.'; end if;
  end if;
  -- Existing sales retain their recorded city. Changes apply to new reports only.
  begin
    if p_id is null then
      insert into public.rotations(team_id,city,municipality_code,start_date,end_date)
      values(p_team,v_m.name,v_m.code,p_start,p_end) returning * into v_row;
    else
      update public.rotations set city=v_m.name,municipality_code=v_m.code,start_date=p_start,end_date=p_end
      where id=p_id returning * into v_row;
    end if;
  exception when exclusion_violation then
    raise exception 'El equipo ya tiene una rotacion en ese periodo. Revisa las fechas.';
  end;
  perform public.log_action('colporteur_rotation_save','rotations',v_row.id,'Destino: ' || v_m.name || ' (' || v_m.department || ')');
  return v_row;
end;
$fn$;

create or replace function public.colporteur_rotation_cancel(p_id uuid)
returns void language plpgsql security definer set search_path = public as $fn$
declare v_row public.rotations%rowtype;
begin
  perform public.assert_can_write();
  perform pg_advisory_xact_lock(160026);
  select * into v_row from public.rotations where id=p_id for update;
  if not found then raise exception 'La rotacion no existe.'; end if;
  if v_row.start_date<=public.cepev_today() then raise exception 'Solo se pueden cancelar rotaciones futuras. Para finalizar una vigente, edita su salida.'; end if;
  delete from public.rotations where id=p_id;
  perform public.log_action('colporteur_rotation_cancel','rotations',p_id,'Rotacion futura cancelada');
end;
$fn$;

-- Keep the legacy RPC compatible, but require an unambiguous municipality.
create or replace function public.rotation_create(p_team uuid,p_city text,p_start date,p_end date)
returns public.rotations language plpgsql security definer set search_path=public as $fn$
declare v_code text; v_count integer;
begin
  perform public.assert_can_write();
  select count(*),min(code) into v_count,v_code from public.colombia_municipalities
  where lower(name)=lower(trim(p_city)) or code=p_city;
  if v_count<>1 then raise exception 'Selecciona el municipio y departamento desde el listado.'; end if;
  return public.colporteur_rotation_save(p_team,v_code,p_start,p_end);
end;
$fn$;

-- Canonical names and codes are checked even when a client writes directly.
create or replace function public.colporteur_validate_city()
returns trigger language plpgsql set search_path=public as $fn$
declare v_m public.colombia_municipalities%rowtype;
begin
  if new.municipality_code is null then raise exception 'Selecciona un municipio del listado.'; end if;
  select * into v_m from public.colombia_municipalities where code=new.municipality_code;
  if not found then raise exception 'Municipio no valido.'; end if;
  if tg_table_name='teams' then new.name := v_m.name || ' (' || v_m.department || ')';
  else new.city := v_m.name; end if;
  return new;
end;
$fn$;
drop trigger if exists colporteur_city on public.teams;
create trigger colporteur_city before insert or update of name,municipality_code on public.teams
for each row execute function public.colporteur_validate_city();
drop trigger if exists colporteur_city on public.rotations;
create trigger colporteur_city before insert or update of city,municipality_code on public.rotations
for each row execute function public.colporteur_validate_city();

create or replace function public.sale_register(p_person uuid,p_date date,p_books integer)
returns public.sales_reports language plpgsql security definer set search_path=public as $fn$
declare v_person public.people%rowtype; v_row public.sales_reports%rowtype;
begin
  perform public.assert_can_write();
  perform pg_advisory_xact_lock(160026);
  select * into v_person from public.people where id=p_person;
  if not found or v_person.kind<>'Colportor' then raise exception 'Selecciona un colportor.'; end if;
  if p_date is null or p_date>public.cepev_today() then raise exception 'Selecciona una fecha hasta hoy.'; end if;
  if p_books is null or p_books<0 then raise exception 'Los libros vendidos deben ser cero o mas.'; end if;
  if exists(select 1 from public.sales_reports where person_id=p_person and report_date=p_date) then
    raise exception 'Ya existe un reporte de ese dia. Usa la opcion de corregir.';
  end if;
  insert into public.sales_reports(person_id,report_date,books_sold,city,team_id,created_by,municipality_code,team_name_snapshot)
  values(p_person,p_date,p_books,public.person_city_on(p_person,p_date),v_person.team_id,auth.uid(),
    public.team_municipality_on(v_person.team_id,p_date),coalesce(public.team_name_on(v_person.team_id,p_date),'Sin equipo'))
  returning * into v_row;
  perform public.log_action('sale_register','sales_reports',v_row.id,'Reporte diario: ' || v_person.full_name || ' (' || p_books || ' libros)');
  return v_row;
end;
$fn$;

create or replace view public.v_colporteur_report_rows with (security_invoker=on) as
select s.id,s.person_id,p.full_name,s.report_date,s.books_sold,s.city,s.municipality_code,
  coalesce(m.name || ' (' || m.department || ')',s.city) as city_label,
  s.team_id,s.team_name_snapshot as team_name
from public.sales_reports s join public.people p on p.id=s.person_id
left join public.colombia_municipalities m on m.code=s.municipality_code;

revoke all on public.v_colporteur_teams,public.v_colporteur_report_rows from public,anon,authenticated;
grant select on public.v_colporteur_teams,public.v_colporteur_report_rows to authenticated;
do $permissions$
declare f text;
begin
  foreach f in array array[
    'team_municipality_on(uuid,date)','team_name_on(uuid,date)',
    'colporteur_team_save(text,uuid)','colporteur_assign_team(uuid,uuid)',
    'colporteur_rotation_save(uuid,text,date,date,uuid)','colporteur_rotation_cancel(uuid)',
    'colporteur_validate_city()'
  ] loop
    execute format('revoke all on function public.%s from public,anon',f);
    execute format('grant execute on function public.%s to authenticated',f);
  end loop;
end;
$permissions$;

create or replace view public.v_colporteur_progress as
select
  p.id                as person_id,
  p.full_name,
  p.daily_goal,
  public.team_name_on(t.id, public.cepev_today()) as team_name,
  public.person_city_on(p.id, public.cepev_today()) as current_city,
  coalesce(sum(sr.books_sold) filter (
    where sr.report_date >= public.cepev_today() - 6), 0)::int as books_last_7d,
  coalesce(sum(sr.books_sold) filter (
    where date_trunc('month', sr.report_date) = date_trunc('month', public.cepev_today())), 0)::int as books_month,
  count(sr.id) filter (
    where sr.report_date >= public.cepev_today() - 6)::int as reports_last_7d,
  max(sr.report_date) as last_report_date
from public.people p
left join public.teams t on t.id = p.team_id
left join public.sales_reports sr on sr.person_id = p.id
where p.kind = 'Colportor'
group by p.id, p.full_name, p.daily_goal, t.id;
create or replace view public.v_people_registry as
select
  p.id,
  p.full_name,
  p.kind,
  p.sex,
  p.birth_date,
  date_part('year', age(p.birth_date))::int as age,
  p.document_type,
  p.document_id,
  p.email,
  p.phone,
  p.base_city,
  p.team_id,
  public.team_name_on(t.id, public.cepev_today()) as team_name,
  p.daily_goal,
  p.is_available,
  p.notes,
  p.created_at,
  public.person_city_on(p.id, public.cepev_today()) as current_city,

  -- Alojamiento vigente, util para la ficha de un cepevista
  (select r.code || ' / ' || b.label
     from public.stays s
     join public.beds b  on b.id = s.bed_id
     join public.rooms r on r.id = b.room_id
    where s.person_id = p.id
      and s.status in ('Reservado', 'Alojado')
      and public.cepev_today() >= s.start_date
      and public.cepev_today() <  s.end_date
    limit 1) as current_bed,

  (select count(*) from public.sales_reports sr where sr.person_id = p.id)::int as reports_count,
  (select coalesce(sum(sr.books_sold), 0)
     from public.sales_reports sr where sr.person_id = p.id)::int               as books_total,
  (select max(sr.report_date)
     from public.sales_reports sr where sr.person_id = p.id)                    as last_report_date,
  (select count(*) from public.stays s  where s.person_id = p.id)::int          as stays_count,
  (select count(*) from public.trips tr where tr.driver_id = p.id)::int         as trips_count,
  (select count(*) from public.kitchen_shifts k where k.person_id = p.id)::int  as shifts_count,

  not exists (select 1 from public.sales_reports sr where sr.person_id = p.id)
  and not exists (select 1 from public.stays s     where s.person_id = p.id)
  and not exists (select 1 from public.trips tr    where tr.driver_id = p.id) as can_delete
from public.people p
left join public.teams t on t.id = p.team_id;
alter view public.v_colporteur_progress set (security_invoker=on);
alter view public.v_people_registry set (security_invoker=on);

create or replace function public.kitchen_block_reason(p_shift uuid, p_person uuid)
returns text
language plpgsql stable
set search_path = public
as $fn$
declare
  v_shift  public.kitchen_shifts%rowtype;
  v_person public.people%rowtype;
  v_city   text;
begin
  select * into v_shift from public.kitchen_shifts where id = p_shift;
  if not found then return 'El turno no existe.'; end if;

  select * into v_person from public.people where id = p_person;
  if not found then return 'La persona no existe.'; end if;

  if not v_person.is_available then
    return 'La persona figura como no disponible.';
  end if;

  if v_person.kind::text not in
       ('Logistica', 'Conductor', 'Administrativo', 'Cepevista', 'Colportor') then
    return 'Los residentes y las llegadas no cubren turnos de cocina.';
  end if;

  -- Fuera de la sede = su equipo esta de rotacion en otra ciudad ese dia.
  -- Antes se comparaba person_city_on(), que cuando no hay rotacion cae en
  -- people.base_city; pero ese campo es la CIUDAD DE PROCEDENCIA, no donde
  -- esta la persona, asi que dejaba fuera de cocina a todo el que no hubiera
  -- nacido en Piedecuesta (practicamente todos los cepevistas).
  select r.city into v_city
    from public.rotations r
    join public.people pe on pe.team_id = r.team_id
   where pe.id = p_person
     and v_shift.service_date >= r.start_date
     and v_shift.service_date <  r.end_date
   limit 1;

  if v_city is not null and v_city <> 'Piedecuesta' then
    return 'Su equipo esta de rotacion en ' || v_city || ' ese dia.';
  end if;

  if exists (
    select 1 from public.kitchen_shifts k
     where k.person_id = p_person
       and k.service_date = v_shift.service_date
       and k.id <> v_shift.id
       and k.starts_at < v_shift.ends_at
       and v_shift.starts_at < k.ends_at
  ) then
    return 'Ya tiene otro turno de cocina que se cruza en ese horario.';
  end if;

  if exists (
    select 1 from public.trips t
     where t.driver_id = p_person
       and t.status in ('Reservado', 'En ruta')
       and tstzrange(t.starts_at, t.ends_at, '[)') && tstzrange(
             (v_shift.service_date + v_shift.starts_at)::timestamptz,
             (v_shift.service_date + v_shift.ends_at)::timestamptz, '[)')
  ) then
    return 'Tiene un recorrido asignado en ese horario.';
  end if;

  if exists (
    select 1 from public.laundry_assignments l
    where l.person_id = p_person and l.service_date = v_shift.service_date
      and l.starts_at < v_shift.ends_at and v_shift.starts_at < l.ends_at
  ) then return 'Tiene una asignacion de lavanderia en ese horario.'; end if;

  if public.team_municipality_on(v_person.team_id, v_shift.service_date) is not null
    and public.team_municipality_on(v_person.team_id, v_shift.service_date) <> '68547' then
    return 'El equipo tiene un municipio asignado fuera de Piedecuesta ese dia.';
  end if;
  return null;
end;
$fn$;
create or replace function public.laundry_block_reason(
  p_date date, p_turn integer, p_machine integer, p_person uuid, p_ignore uuid default null
) returns text language plpgsql set search_path = public as $fn$
declare
  v_person public.people%rowtype;
  v_start time := case p_turn when 1 then time '11:00' else time '15:00' end;
  v_end time := case p_turn when 1 then time '13:00' else time '17:00' end;
begin
  select * into v_person from public.people where id = p_person;
  if not found then return 'La persona no existe.'; end if;
  if not v_person.is_available then return 'La persona figura como no disponible.'; end if;
  if p_machine > 0 and v_person.kind::text not in ('Cepevista','Colportor','Logistica','Conductor','Administrativo') then
    return 'La persona no pertenece al personal elegible para lavanderia.';
  end if;
  if exists (
    select 1 from public.rotations r where r.team_id = v_person.team_id
      and p_date >= r.start_date and p_date < r.end_date and r.city <> 'Piedecuesta'
  ) then return 'Su equipo esta de rotacion en otra ciudad ese dia.'; end if;
  if exists (
    select 1 from public.laundry_assignments l where l.service_date = p_date and l.turn = p_turn
      and l.person_id = p_person and (p_ignore is null or l.id <> p_ignore)
  ) then return 'Ya tiene otra asignacion de lavanderia en ese turno.'; end if;
  if exists (
    select 1 from public.kitchen_shifts k where k.service_date = p_date and k.person_id = p_person
      and k.starts_at < v_end and v_start < k.ends_at
  ) then return 'Tiene un turno de cocina que se cruza en ese horario.'; end if;
  if exists (
    select 1 from public.trips t where t.driver_id = p_person and t.status in ('Reservado','En ruta')
      and t.starts_at < ((p_date + v_end) at time zone 'America/Bogota')
      and ((p_date + v_start) at time zone 'America/Bogota') < t.ends_at
  ) then return 'Tiene un recorrido asignado en ese horario.'; end if;
  if public.team_municipality_on(v_person.team_id, p_date) is not null
    and public.team_municipality_on(v_person.team_id, p_date) <> '68547' then
    return 'El equipo tiene un municipio asignado fuera de Piedecuesta ese dia.';
  end if;
  return null;
end;
$fn$;

-- A new base city changes future operational availability for team members.
create or replace function public.colporteur_team_changed()
returns trigger language plpgsql security definer set search_path=public as $fn$
begin
  perform pg_advisory_xact_lock(150025);
  delete from public.laundry_publications lp where lp.service_date>=public.cepev_today()
    and exists(select 1 from public.laundry_assignments l join public.people p on p.id=l.person_id
      where l.service_date=lp.service_date and p.team_id=new.id);
  delete from public.kitchen_publications kp where kp.service_date>=public.cepev_today()
    and exists(select 1 from public.kitchen_shifts k join public.people p on p.id=k.person_id
      where k.service_date=kp.service_date and p.team_id=new.id);
  return null;
end;
$fn$;
revoke all on function public.colporteur_team_changed() from public,anon,authenticated;
drop trigger if exists colporteur_team_changed on public.teams;
create trigger colporteur_team_changed after update of municipality_code on public.teams
for each row when (old.municipality_code is distinct from new.municipality_code)
execute function public.colporteur_team_changed();

commit;
